urlset:
{{ base_url }}/
{% for std in standards %}
{{ base_url }}/{{ std.id }}
{% for ml in std.sorted_major_lines() %}
{{ base_url }}/{{ std.id }}/v{{ ml.major }}
{% for rules in std.sorted_rules(ml.major) %}
{{ base_url }}/{{ std.id }}/{{ rules.slug }}
{% endfor %}
{% endfor %}
{% for rel in std.sorted_releases() %}
{{ base_url }}/{{ std.id }}/{{ rel.slug }}
{% endfor %}
{% endfor %}
